MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    error, grid, observations, fill_value = _validate_spec(raw)
