from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    error, grid, observations, fill_value = _validate_spec(raw)
    if error is not None:
        return {"ok": False, "error": error}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    tolerance = cell_size // 2

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _project(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped = dropped + 1
            continue
        row = _project(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    rows = _render_rows(sums, counts, degraded, width, height, fill_value)
    coverage = len(counts) * 100 // (width * height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": rows[0],
        "flags": rows[1],
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_spec(raw: object) -> tuple:
    """Validate the whole payload; return the (possibly None) error and parsed parts."""
    if not isinstance(raw, dict):
        return "malformed input", None, None, None
    if not _has_all(raw, ("grid", "observations", "fill_value")):
        return "missing field", None, None, None
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return "bad grid", None, None, None
    if not _has_all(grid, ("width", "height", "cell_size")):
        return "bad grid", None, None, None
    if not _dim(grid["width"], MAX_DIM):
        return "bad width", None, None, None
    if not _dim(grid["height"], MAX_DIM):
        return "bad height", None, None, None
    if not isinstance(grid["cell_size"], int) or grid["cell_size"] < 1:
        return "bad cell size", None, None, None
    if not isinstance(raw["fill_value"], int):
        return "bad fill value", None, None, None
    observations = raw["observations"]
    if not isinstance(observations, list):
        return "bad observations", None, None, None
    if not all(_valid_observation(obs) for obs in observations):
        return "bad observation", None, None, None
    return None, grid, observations, raw["fill_value"]


def _has_all(container: dict, fields: tuple) -> bool:
    return all(field in container for field in fields)


def _dim(value: object, limit: int) -> bool:
    return isinstance(value, int) and 1 <= value <= limit


def _valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in _OBS_FIELDS:
        if field not in obs or not isinstance(obs[field], int):
            return False
    return 0 <= obs["quality"] <= 100


def _project(value: int, dim: int, cell_size: int, tolerance: int):
    """Map a coordinate onto the grid, clamping the last partial cell; None means dropped."""
    if value < 0:
        return None
    cell = value // cell_size
    if cell >= dim:
        if value - dim * cell_size >= tolerance:
            return None
        cell = dim - 1
    return cell


def _render_rows(sums: dict, counts: dict, degraded: dict, width: int, height: int, fill_value: int) -> tuple:
    """Render the accumulated sums/counts into output cell and flag grids."""
    cells = []
    flags = []
    for row in range(height):
        cell_row = []
        flag_row = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cell_row.append(sums[key] // counts[key])
                flag_row.append("degraded" if key in degraded else "good")
            else:
                cell_row.append(fill_value)
                flag_row.append("empty")
        cells.append(cell_row)
        flags.append(flag_row)
    return cells, flags


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

